def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    my_c = me.count('C')
    my_d = n - my_c

    # Recent window statistics (weighted toward recent behavior).
    w = 12
    recent = history[-w:] if n >= w else history
    r_len = len(recent)
    r_op_c = sum(1 for _, o in recent if o == 'C')
    r_op_d = r_len - r_op_c
    r_my_c = sum(1 for m, _ in recent if m == 'C')

    last_my, last_op = history[-1]

    # Endgame: with only a few rounds left, exploit cooperative opponents.
    remaining = 100 - n
    if remaining <= 2:
        if op_c >= max(1, op_d):
            return 'D'
        return 'D' if op_d >= op_c else 'C'

    if remaining <= 4:
        if op_c > op_d:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Defect heavily against an always-defect or near always-defect opponent.
    if n >= 6 and op_c == 0:
        return 'D'
    if n >= 12 and op_d >= n - 1:
        return 'D'

    # Against a nearly always cooperative opponent, keep cooperating early,
    # then exploit in the endgame.
    if n >= 8 and op_d <= max(1, n // 12):
        return 'C'

    # Retaliate promptly but not permanently against recent defections.
    if last_op == 'D':
        # Count consecutive opponent defections.
        streak_d = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                streak_d += 1
            else:
                break
        streak_c = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'C':
                streak_c += 1
            else:
                break

        # Long defection war: try to restart cooperation occasionally.
        if streak_d >= 3:
            if rng.random() < 0.18:
                return 'C'
            return 'D'

        # Opponent mostly cooperative but just defected: one-shot punishment,
        # then forgive to restore mutual cooperation.
        if op_c >= op_d and streak_d == 1:
            return 'D'

        # Mixed / persistent defection: retaliate.
        if r_op_d * 2 >= r_len:
            return 'D'
        if streak_d >= 2:
            return 'D'
        return 'D'

    # Opponent cooperated last.
    if last_op == 'C':
        # If we defected last and they still cooperated, keep cooperating to
        # rebuild trust, but occasionally probe a very cooperative opponent.
        if last_my == 'D':
            return 'C'

        # Probe occasionally against highly cooperative opponents in midgame.
        if n > 15 and remaining > 8 and op_c * 5 >= n * 4:
            if n % 11 == 0 and rng.random() < 0.35:
                return 'D'
            return 'C'

        # If recent opponent cooperation is high, cooperate.
        if r_op_c * 2 >= r_len:
            return 'C'

        # Otherwise cautious cooperation.
        if op_c >= op_d:
            return 'C'
        return 'D' if rng.random() < 0.3 else 'C'

    return 'C'
